const [isPublishing, setIsPublishing] = useState(false);

const publishShifts = async () => {
  const draftShifts = schedules.filter(s => s.isDraft && s.crewId !== 'openshifts');
  if (draftShifts.length === 0) {
    alert("No draft shifts assigned to crew members found to publish.");
    return;
  }

  if (!confirm(`Are you sure you want to publish ${draftShifts.length} draft shifts? This will send email notifications to the assigned crew members.`)) {
    return;
  }

  setIsPublishing(true);

  try {
    const updatedSchedules = schedules.map(s => {
      if (s.isDraft && s.crewId !== 'openshifts') {
        return {
          ...s,
          isDraft: false,
          approvalStatus: 'pending' as const
        };
      }
      return s;
    });

    const shiftsByCrew: { [crewId: string]: typeof draftShifts } = {};
    draftShifts.forEach(shift => {
      if (!shiftsByCrew[shift.crewId]) {
        shiftsByCrew[shift.crewId] = [];
      }
      shiftsByCrew[shift.crewId].push(shift);
    });

    const getCrewEmailAddress = (crewId: string) => {
      const u = users.find(user => user.id === crewId);
      if (u && u.email) return u.email;
      return `${crewId}@7thheavenband.com`;
    };

    const emailPromises = Object.entries(shiftsByCrew).map(async ([crewId, shifts]) => {
      const crewName = shifts[0].crewName || findCrewName(crewId);
      const emailTo = getCrewEmailAddress(crewId);
      const subject = `📅 New Shift Assignments Published — action required`;

      const shiftsHtml = shifts.map(s => {
        return `
          <div style="margin-bottom: 20px; padding: 15px; border: 1px solid #e5e7eb; border-radius: 8px; background-color: #f9fafb;">
            <h3 style="margin: 0 0 5px 0; color: #1f2937;">${s.role}</h3>
            <p style="margin: 0 0 5px 0; font-size: 14px; color: #4b5563;">
              <strong>Date:</strong> ${s.date}<br/>
              <strong>Time:</strong> ${s.time}<br/>
              <strong>Location:</strong> ${s.location}
            </p>
            ${s.notes ? `<p style="margin: 5px 0 0 0; font-size: 13px; color: #6b7280; font-style: italic;"><strong>Notes:</strong> ${s.notes}</p>` : ''}
          </div>
        `;
      }).join('');

      const html = `
        <div style="font-family: sans-serif; max-width: 600px; margin: 0 auto; color: #374151;">
          <h2 style="color: #851def; margin-bottom: 20px;">Hello ${crewName},</h2>
          <p style="font-size: 15px; line-height: 1.5; margin-bottom: 20px;">
            Management has published new shift assignments for you. Please check your Crew Dashboard to approve or decline these shifts.
          </p>
          <h4 style="margin: 0 0 10px 0; text-transform: uppercase; font-size: 12px; color: #9ca3af; letter-spacing: 0.05em;">Published Shifts:</h4>
          ${shiftsHtml}
          <p style="margin-top: 30px; font-size: 14px;">
            <a href="${window.location.origin}/crew" style="display: inline-block; padding: 10px 20px; background-color: #851def; color: #ffffff; text-decoration: none; border-radius: 6px; font-weight: bold;">
              Go to Crew Dashboard
            </a>
          </p>
          <p style="margin-top: 40px; font-size: 12px; color: #9ca3af; border-top: 1px solid #e5e7eb; padding-top: 15px;">
            This is an automated notification from the 7th Heaven Platform.
          </p>
        </div>
      `;

      const res = await fetch('/api/email', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ to: emailTo, subject, html })
      });
      return res;
    });

    await Promise.all(emailPromises);

    setSchedules(updatedSchedules);
    localStorage.setItem('7h_crew_schedules', JSON.stringify(updatedSchedules));
    window.dispatchEvent(new Event('storage'));

    const syncRes = await fetch("/api/crew/calendar", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(updatedSchedules)
    });

    if (syncRes.ok) {
      alert(`Successfully published ${draftShifts.length} shifts. Shift emails sent to crew!`);
      setAuditLog(prev => [{
        id: crypto.randomUUID(),
        text: `📤 Published ${draftShifts.length} crew shifts and sent email notifications.`,
        time: "Just now",
        color: "bg-purple-600"
      }, ...prev]);
    } else {
      throw new Error("Failed to sync calendar updates.");
    }

  } catch (err: any) {
    console.error(err);
    alert("Error publishing shifts: " + (err.message || err));
  } finally {
    setIsPublishing(false);
  }
};
